import{_ as a}from"./chunks/L0C2UB_Function_Combination_950.C-IY8h-0.js";import{_ as n,o as p,a as t,b as l}from"./app.DKoEZOcr.js";const i="/ascendc.github.io/pr/5487/assets/no_nz2nd_single_mode.B_ci6GsX.png",c="/ascendc.github.io/pr/5487/assets/no_nz2nd_dual_target_mode.CA4xJoL2.png",e="/ascendc.github.io/pr/5487/assets/enable_nz2nd_config.CIyDI403.png",r="/ascendc.github.io/pr/5487/assets/enable_nz2nd_single_load.DSCR45dS.png",d="/ascendc.github.io/pr/5487/assets/enable_nz2nd_dual_load.uH77_0t7.png",o="/ascendc.github.io/pr/5487/assets/enable_nz2dn_single_mode1.Cmk5GkL4.png",_="/ascendc.github.io/pr/5487/assets/enable_nz2dn_single_mode2.Cz7VWL4s.png",S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/cube_compute_store"},{"text":"Fixpipe（L0C到UB数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToUB"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToUB.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToUB.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":3,"title":"不开启NZ2ND随路格式转换","slug":"不开启NZ2ND随路格式转换","link":"#不开启NZ2ND随路格式转换"},{"level":3,"title":"开启NZ2ND随路格式转换","slug":"开启NZ2ND随路格式转换","link":"#开启NZ2ND随路格式转换"},{"level":3,"title":"开启NZ2DN随路格式转换","slug":"开启NZ2DN随路格式转换","link":"#开启NZ2DN随路格式转换"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),u={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/Fixpipe_L0CToUB.md"};function N(b,s,h,f,m,g){return p(),t("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>Fixpipe（L0C Buffer到UB数据搬运）<span id="ZH-CN_TOPIC_0000002563847576"></span></h1><h2 id="产品支持情况">产品支持情况<span id="zh-cn_topic_0000002549846732_section796754519912"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持包含FixpipeParamsArch3510参数的接口。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持包含FixpipeParamsM300参数的接口。</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000002549846732_section106841136114319"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_fixpipe_intf.h&quot;</code>。</p><p>矩阵计算的结果存放在L0C Buffer，Fixpipe接口用于将结果搬运至Unified Buffer（UB）中，并且在搬运过程中支持随路格式转换等操作。</p><div data-filter="950"><p>以Ascend 950PR/Ascend 950DT为例，下图展示了随路量化、随路ReLU、随路通道合并的有效组合、中间数据类型和数据路径。下图中的F32-&gt;F16与F32-&gt;BF16为非量化模式，仅为Cast，其余为随路scalar/tensor量化模式。</p><p><strong>图2</strong> L0C2UB流程图<a id="zh-cn_topic_0000002542828493_fig1828513492547"></a></p><p><img src="'+a+`" alt></p></div><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000002549846732_section82039854412"></span><a class="header-anchor" href="#函数原型">​</a></h2><p>L0C Buffer到UB数据搬运提供矩阵搬出的组合接口Fixpipe，接口内包含了设置寄存器与数据搬运能力，对应的接口如下：</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT：</p><ul><li><p>通路L0C Buffer-&gt;UB，不开启tensor量化功能：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeConfig</span><span class="o">&amp;</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Fixpipe</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeParamsArch3510</span><span class="o">&lt;</span><span class="n">config</span><span class="p">.</span><span class="n">format</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li><li><p>通路L0C Buffer-&gt;UB，开启tensor量化功能：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeConfig</span><span class="o">&amp;</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Fixpipe</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">cbufWorkspace</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeParamsArch3510</span><span class="o">&lt;</span><span class="n">config</span><span class="p">.</span><span class="n">format</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li></ul></div><div data-filter="310b"><p>针对Atlas 200I/500 A2 推理产品：</p><ul><li><p>通路L0C Buffer-&gt;UB，不开启tensor量化功能：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeConfig</span><span class="o">&amp;</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Fixpipe</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeParamsM300</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li><li><p>通路L0C Buffer-&gt;UB，开启tensor量化功能：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeConfig</span><span class="o">&amp;</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="kt">uint64_t</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Std</span><span class="o">::</span><span class="n">enable_if</span><span class="o">&lt;</span><span class="n">Std</span><span class="o">::</span><span class="n">is_same</span><span class="o">&lt;</span><span class="n">PrimT</span><span class="o">&lt;</span><span class="n">S</span><span class="o">&gt;</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">&gt;::</span><span class="n">value</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="o">&gt;::</span><span class="n">type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Fixpipe</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">S</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">cbufWorkspace</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">FixpipeParamsM300</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></li></ul></div><p><strong>注意：</strong></p><ul><li><strong>调用L0C Buffer到UB的Fixpipe接口时，模板参数“const FixpipeConfig&amp; config”的值不能使用<code>CFG_ROW_MAJOR</code>、<code>CFG_COLUMN_MAJOR</code>、<code>CFG_NZ</code>，而需要显式构造<code>isToUB = true</code>的配置，表示目的物理地址为UB。</strong></li></ul><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000002549846732_section16128134420472"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> Fixpipe模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T/U</td><td>目的操作数/源操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002549846732_section4219135304818">数据类型</a>。</td></tr><tr><td>config</td><td>Fixpipe相关配置参数，类型为FixpipeConfig，需要显式构造<code>isToUB = true</code>的配置，表示目的物理地址为UB，构造示例如下：<br>开启NZ2ND，输出数据格式为ND格式：<br>constexpr AscendC::FixpipeConfig CFG_ROW_MAJOR_UB = {AscendC::CO2Layout::ROW_MAJOR, true};<br>NZ2NZ，输出数据格式为NZ格式：<br>constexpr AscendC::FixpipeConfig CFG_NZ_UB = {AscendC::CO2Layout::NZ, true};<br>开启NZ2DN，输出数据格式为DN格式：<br>constexpr AscendC::FixpipeConfig CFG_COLUMN_MAJOR_UB = {AscendC::CO2Layout::COLUMN_MAJOR, true};<br>FixpipeConfig结构体定义如下：<br>struct FixpipeConfig {<br> CO2Layout format;<br> bool isToUB; // 用于用户指定目的地址的位置是否是UB <br>};<br>enum class CO2Layout : uint8_t {<br> NZ = 0, // 输出数据格式仍为NZ格式。<br> ROW_MAJOR, // 开启NZ2ND，输出数据格式为ND格式。<br><span data-filter="950"> COLUMN_MAJOR, // 仅Ascend 950PR/Ascend 950DT支持，开启NZ2DN，输出数据格式为DN格式。<br></span>};<br>constexpr FixpipeConfig CFG_NZ = {CO2Layout::NZ};<br>constexpr FixpipeConfig CFG_ROW_MAJOR = {CO2Layout::ROW_MAJOR};<span data-filter="950"><br>constexpr FixpipeConfig CFG_COLUMN_MAJOR = {CO2Layout::COLUMN_MAJOR}; // 仅Ascend 950PR/Ascend 950DT支持</span></td></tr><tr><td>S</td><td>参数cbufWorkspace的数据类型，即随路量化参数的数据类型。<br>  •当目的操作数、源操作数、cbufWorkspace使用基础数据类型时，模板参数S必须为uint64_t类型，否则编译失败。<br>  •当目的操作数、源操作数、cbufWorkspace使用TensorTrait类型时，模板参数S的LiteType必须为uint64_t类型，否则编译失败。<br>模板参数S后一个模板参数仅用于上述数据类型检查，用户无需关注。</td></tr></tbody></table><p><strong>表2</strong> Fixpipe参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，地址需满足32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，支持的物理地址为L0C Buffer（TPosition为CO1），为Mmad接口计算的结果。数据格式为NZ格式，地址需要满足64B对齐。</td></tr><tr><td>intriParams</td><td>输入</td><td>Fixpipe搬运参数，具体定义请参考&quot;basic_api/kernel_struct_fixpipe.h&quot;。<br>参数说明请参考Fixpipe搬运参数（FixpipeParamsArch3510、FixpipeParamsM300）结构体说明。</td></tr><tr><td>cbufWorkspace</td><td>输入</td><td>量化参数，类型为<code>LocalTensor&lt;uint64_t&gt;</code>，支持的物理地址为L1 Buffer（TPosition为C1），地址需满足32字节对齐。<br>  •当quantPre为VDEQF16、VQF322B8_PRE、VREQ8时支持。<br><span data-filter="950">  •针对Ascend 950PR/Ascend 950DT，除上述外还有VQF322FP8_PRE、VQF322HIF8_PRE、VQF322HIF8_PRE_HYBRID、VQS322BF16_PRE、VQF322F16_PRE、VQF322BF16_PRE、VQF322F32_PRE支持。<br></span>quantPre介绍请参考Fixpipe搬运参数结构体中quantPre部分。</td></tr></tbody></table><p><strong>表3</strong> Fixpipe搬运参数（FixpipeParamsArch3510）结构体说明</p><table><thead><tr><th>参数名称</th><th>数据类型</th><th>含义</th></tr></thead><tbody><tr><td>nSize</td><td>必选输入</td><td>源NZ矩阵在N方向上的大小，取值范围为nSize∈[0, 4095]。<br>  • 若开启<a href="../cube_store_key_features/F32-Channel-Split.html">channelSplit功能</a>功能，nSize必须为8的倍数。<br>  • 若不开启channelSplit功能，nSize必须为16的倍数。<br>  • 若开启NZ2ND，nSize*sizeof(T)必须为32的倍数。<br><strong>注：nSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>mSize</td><td>必选输入</td><td>源NZ矩阵在M方向上的大小，取值范围为mSize∈[0, 65535]。若开启NZ2DN，mSize*sizeof(T)必须为32的倍数。<br><strong>注：mSize=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcStride</td><td>必选输入</td><td>源NZ矩阵中相邻Z排布的起始地址偏移，取值范围为srcStride∈[0, 65535]，单位为C0_Size（16*sizeof(T)），T为src的数据类型，其值应填成mSize对16向上取整。</td></tr><tr><td>dstStride</td><td>必选输入</td><td>• 不开启NZ2ND/NZ2DN功能（<a href="../cube_store_key_features/NZ2NZ.html">NZ2NZ搬运</a>）：目的NZ矩阵中相邻Z排布的起始地址偏移，取值不为0，单位为element。（与Fixpipe搬运参数（FixpipeParamsV220）中的dstStride相比，二者的单位发生了变化，FixpipeParamsV220中dstStride的单位为datablock（32字节），而FixpipeParamsArch3510中dstStride的单位为element。）<br>• 开启<a href="../cube_store_key_features/NZ2ND.html">NZ2ND</a>/<a href="../cube_store_key_features/NZ2DN.html">NZ2DN</a>功能：目的ND/DN矩阵每一行中的元素个数，取值不为0，单位为element。</td></tr><tr><td><a href="../cube_store_key_features/accompanying_quantization.html">quantPre</a></td><td>可选输入</td><td>用于控制量化模式，QuantMode_t类型，默认值为<code>QuantMode_t::NoQuant</code>，具体定义如下：<br>注：此参数需要用户手动配置，不会自动推导配置对应量化模式。<br>enum QuantMode_t<br>{<br> NoQuant, // 不开启量化功能<br> F322F16, // Float32_2_Float16: float cast成half，cast mode为CAST_RINT模式<br> F322BF16, // Float32_2_BFloat16 :float cast成bfloat16_t，cast mode为CAST_RINT模式<br> DEQF16, // DeQuant_Float16: int32_t量化成half, scalar量化<br> VDEQF16, // Vector_DeQuant_Float16: int32_t量化成half，tensor量化<br> QF322B8_PRE, // Quant_Float32_2_B8: float量化成int8_t/uint8_t，scalar量化<br> VQF322B8_PRE, // Vector_Quant_Float32_2_B8: float量化成int8_t/uint8_t，tensor量化<br> REQ8, // ReQuant_int8: int32_t量化成int8_t/uint8_t，scalar量化<br> VREQ8, // Vector_ReQuant_int8: int32_t量化成int8_t/uint8_t，tensor量化<br> QF322FP8_PRE, // Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，scalar量化<br> VQF322FP8_PRE, // Vector_Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，tensor量化<br> QF322HIF8_PRE, // Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，scalar量化<br> VQF322HIF8_PRE, // Vector_Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，tensor量化<br> QF322HIF8_PRE_HYBRID, // Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，scalar量化<br> VQF322HIF8_PRE_HYBRID, // Vector_Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，tensor量化<br> QS322BF16_PRE, // Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，scalar量化<br> VQS322BF16_PRE, // Vector_Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，tensor量化<br> QF322F16_PRE, // Quant_Float32_2_Float16: float量化成half，scalar量化<br> VQF322F16_PRE, // Vector_Quant_Float32_2_Float16: float量化成half，tensor量化<br> QF322BF16_PRE, // Quant_Float32_2_BFloat16: float量化成bfloat16_t，scalar量化<br> VQF322BF16_PRE, // Vector_Quant_Float32_2_BFloat16: float量化成bfloat16_t，tensor量化<br> QF322F32_PRE, // Quant_Float32_2_Float32: float量化成float，scalar量化，精度可以达到双千分之一，无法达到双万分之一。如果有双万分之一的精度要求，建议使用<a href="../../../adv_api/quantization/AscendDequant.html">AscendDeQuant</a>高阶API。<br> VQF322F32_PRE, // Vector_Quant_Float32_2_Float32: float量化成float，tensor量化，精度可以达到双千分之一，无法达到双万分之一。如果有双万分之一的精度要求，建议使用<a href="../../../adv_api/quantization/AscendDequant.html">AscendDeQuant</a>高阶API。<br>};</td></tr><tr><td>deqScalar</td><td>可选输入</td><td>scalar量化参数，表示单个scale值，quantPre量化模式为<a href="../cube_store_key_features/accompanying_quantization.html">随路量化</a>时需要设置该参数。支持的数据类型为<code>uint64_t</code>。</td></tr><tr><td><a href="../cube_store_key_features/accompanying_relu.html">reluEn</a></td><td>可选输入</td><td>是否开启NormReLU的开关：<br>  • <code>false</code>：不开启NormReLU功能， 默认为<code>false</code>；<br>  • <code>true</code>：开启NormReLU功能。</td></tr><tr><td>unitFlag</td><td>可选输入</td><td>unitFlag是一种Mmad指令和Fixpipe指令细粒度的并行，开启该功能后，硬件每计算完一个分形，计算结果就会被搬出。取值说明如下：<br>  • 0（2&#39;b00）：不开启unitFlag；<br>  • 2（2&#39;b10）：开启unitFlag，硬件执行完指令之后，不复位单元标记位；<br>  • 3（2&#39;b11）：开启unitFlag，硬件执行完指令之后，复位单元标记位。<br>开启该功能时，须将Mmad指令和Fixpipe指令的unitFlag值设置为2或3。<br>参数设置方案和特性细节可参考：Mmad计算中关键特性说明的<a href="../mmad_compute_key_features/UnitFlag.html">UnitFlag</a>章节。</td></tr><tr><td>params</td><td>可选输入</td><td>用于选择和配置不同的随路格式转换（NZ2NZ/NZ2ND/NZ2DN），该参数为TransformParams类型的结构体。TransformParams结构体是一个基于模板参数的类型选择器，用于在编译时根据定义FixpipeParamsArch3510搬运参数时使用的模板参数，自动选择对应的参数类型。<br>template &lt;CO2Layout format&gt;<br>struct TransformParams {};<br>template &lt;&gt;<br>struct TransformParams&lt;CO2Layout::NZ&gt; {<br> __aicore__ inline TransformParams(){};<br> using PARAMS = uint8_t;<br>};<br>template &lt;&gt;<br>struct TransformParams&lt;CO2Layout::ROW_MAJOR&gt; {<br> __aicore__ inline TransformParams(){};<br> using PARAMS = Nz2NdParams;<br>};<br>template &lt;&gt;<br>struct TransformParams&lt;CO2Layout::COLUMN_MAJOR&gt; {<br> __aicore__ inline TransformParams(){};<br> using PARAMS = Nz2DnParams;<br>};<br>CO2Layout布局类型为ROW_MAJOR时， 该指令被定义为从L0C Buffer到目标位置的数据移动，并附带NZ2ND转换，结构体参数如下：<br>struct Nz2NdParams {<br> uint16_t ndNum = 1;<br> uint16_t srcNdStride = 0;<br> uint32_t dstNdStride = 0; <br>};<br>  • ndNum：源NZ矩阵的数目，也就是传输ND矩阵的数目，取值范围为ndNum∈[0, 65535]。<strong>注：ndNum=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong><br>  • srcNdStride：不同NZ矩阵起始地址之间的间隔，取值范围为srcNdStride∈[0, 65535]，单位为C0_SIZE。当ndNum配置为1时，srcNdStride配置为0即可，不生效。<br>  • dstNdStride：目的相邻ND矩阵起始地址之间的偏移，取值范围为dstNdStride∈[1, 2^32 -1]，单位为element。当ndNum配置为1时，dstNdStride配置为0即可，不生效。<br><br>CO2Layout布局类型为COLUMN_MAJOR时， 该指令被定义为从L0C Buffer到目标位置的数据移动，并附带NZ2DN转换，结构体参数如下：<br>struct Nz2DnParams {<br> uint16_t dnNum = 1;<br> uint16_t srcNzMatrixStride = 0;<br> uint32_t dstDnMatrixStride = 0;<br> uint16_t srcNzC0Stride = 0; <br>};<br>  • dnNum：传输DN矩阵的数目，取值范围为dnNum∈[0, 65535]。<strong>注：dnNum=0表示不执行搬运，该接口将被视为NOP（空操作）。</strong><br>  • srcNzMatrixStride：不同源NZ矩阵的偏移（头与头），取值范围srcNzMatrixStride∈[0, 65535]，单位C0_SIZE。当dnNum配置为1时，srcNzMatrixStride配置为0即可，不生效。<br>  • dstDnMatrixStride：目的相邻ND矩阵起始地址之间的偏移，取值范围dstDnMatrixStride∈[0, 2^32 -1]，单位element。当dnNum配置为1时，dstDnMatrixStride配置为0即可，不生效。<br>  • srcNzC0Stride：源矩阵NZ分形中相邻行的地址偏移（头与头），取值范围srcNzC0Stride∈[0, 65535]，单位C0_SIZE。当启用NZ2DN时，srcNzC0Stride不能为0。<br><br>CO2Layout布局类型为NZ时，为普通搬运DMA模式，表示从L0C Buffer到目标位置的正常数据移动。</td></tr><tr><td>dualDstCtrl</td><td>可选输入</td><td>双目标模式控制参数。对于Ascend 950PR/Ascend 950DT，同一AI Core内有一个Cube Core和两个Vector Core，当启用双目标模式控制时，L0C Buffer中的M×N矩阵将被分成两半，并同时分别写入两个Vector Core各自的UB中，其中前半部分写入SUB BLOCK0，后半部分写入SUB BLOCK1。<br>  • 2&#39;b00：单目标模式，将整个矩阵写入通过subBlockId参数配置的目标UB。<br>  • 2&#39;b01：双目标模式，按M维度拆分成形状为M / 2 * N的两个矩阵，分别写入两个UB, M必须为2的倍数。<br>  • 2&#39;b10：双目标模式，按N维度拆分成形状为M * N / 2的两个矩阵，分别写入两个UB, N须为32的倍数。<br>  • 2&#39;b11：保留值。<br>dualDstCtrl仅支持在普通搬运模式（NZ2NZ）或NZ2ND搬运场景下使用，不支持随路功能场景。<br>参数设置方案和特性细节可参考：<a href="../cube_store_key_features/L0C_to_UB_dual_target_mode.html">L0C到UB双目标模式</a></td></tr><tr><td>subBlockId</td><td>可选输入</td><td>启用单目标模式时用于指示目标UB的SUB BLOCK ID。取值为0或1，取值为0时写入SUB BLOCK0，为1时写入SUB BLOCK1，默认为0。</td></tr><tr><td><a href="../cube_store_key_features/F32-Channel-Split.html">isChannelSplit</a></td><td>可选输入</td><td>此参数仅在L0C Buffer到Global Memory通路下有效。</td></tr></tbody></table><p><strong>表4</strong> Fixpipe搬运参数（FixpipeParamsM300）结构体说明</p><table><thead><tr><th>参数名称</th><th>数据类型</th><th>含义</th></tr></thead><tbody><tr><td>nSize</td><td>输入</td><td>源NZ矩阵在N方向上的大小，取值范围为nSize ∈[1, 4095]。<br>  •若开启channelSplit功能，nSize必须为8的倍数。<br>  •若不开启channelSplit功能，nSize必须为16的倍数。</td></tr><tr><td>mSize</td><td>输入</td><td>源NZ矩阵在M方向上的大小。<br>  •不开启NZ2ND功能，取值范围为mSize∈[1, 65535]。<br>  •开启NZ2ND功能，取值范围为mSize∈[1, 8192]。</td></tr><tr><td>srcStride</td><td>输入</td><td>源NZ矩阵中相邻Z排布的起始地址偏移，取值范围为srcStride∈[0, 65535]，单位为C0_SIZE(16*sizeof(T)，T为src的数据类型)。</td></tr><tr><td>dstStride</td><td>输入</td><td>•不开启NZ2ND功能，目的NZ矩阵中相邻Z排布的起始地址偏移，取值不为0，单位为datablock(32字节)。<br>•开启NZ2ND功能，目的ND矩阵每一行中的元素个数，取值不为0，单位为element。</td></tr><tr><td>quantPre</td><td>输入</td><td>QuantMode_t是一个枚举类型，用于控制量化模式，默认值为QuantMode_t::NoQuant，即不开启量化功能。QuantMode_t取值如下：<br>  • NoQuant，不开启量化功能。<br>  • F322F16，float cast成half，cast mode为CAST_RINT模式。<br>  • F322BF16，float cast成bfloat16_t，cast mode为CAST_RINT模式。<br>  • DEQF16，int32_t量化成half，scalar量化。<br>  • VDEQF16，int32_t量化成half，tensor量化。<br>  • QF322B8_PRE，float量化成uint8_t/int8_t，scalar量化。<br>  • VQF322B8_PRE，float量化成uint8_t/int8_t，tensor量化。<br>  • REQ8，int32_t量化成uint8_t/int8_t，scalar量化。<br>  • VREQ8，int32_t量化成uint8_t/int8_t，tensor量化</td></tr><tr><td>deqScalar</td><td>输入</td><td>scalar量化参数，表示单个scale值，quantPre量化模式为scalar量化时需要设置该参数。支持的数据类型为uint64_t。</td></tr><tr><td>ndNum</td><td>输入</td><td>源NZ矩阵的数目，也就是传输ND矩阵的数目，取值范围为ndNum∈[1, 65535]。</td></tr><tr><td>srcNdStride</td><td>输入</td><td>不同NZ矩阵起始地址之间的间隔。当ndNum大于1时，取值范围为srcNdStride∈[1, 512]；当ndNum配置为1时，srcNdStride可配置为0，此时不生效。单位为数据块（16 * C0_SIZE）。</td></tr><tr><td>dstNdStride</td><td>输入</td><td>目的相邻ND矩阵起始地址之间的偏移，取值范围为dstNdStride∈[1, 65535]，单位为element。当ndNum配置为1时，dstNdStride配置为0即可，不生效。</td></tr><tr><td>reluEn</td><td>输入</td><td>是否开启ReLU的开关：<br>  • false：不开启ReLU功能；<br>  • true：开启ReLU功能。</td></tr><tr><td>unitFlag</td><td>输入</td><td>unitFlag是一种Mmad指令和Fixpipe指令细粒度的并行，开启该功能后，硬件每计算完一个分形，计算结果就会被搬出，该功能不适用于在L0C Buffer累加的场景。取值说明如下：<br>  • 0（2&#39;b00）：不开启unitFlag；<br>  • 2（2&#39;b10）：开启unitFlag，硬件执行完指令之后，不会设置寄存器；<br>  • 3（2&#39;b11）：开启unitFlag，硬件执行完指令之后，会将unitFlag关闭。</td></tr><tr><td><a href="../cube_store_key_features/F32-Channel-Split.html">isChannelSplit</a></td><td>输入</td><td>此参数仅在L0C Buffer到Global Memory通路下有效。</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="zh-cn_topic_0000002549846732_section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p><strong>源矩阵与目的矩阵支持的数据类型组合</strong></p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（UB）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、hifloat8_t、fp8_e4m3fn_t、half、bfloat16_t、float。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half、bfloat16_t、int32_t。</td></tr></tbody></table></div><div data-filter="310b"><p>针对Atlas 200I/500 A2 推理产品，支持的数据类型组合如下：</p><table><thead><tr><th>源矩阵（L0C Buffer）</th><th>目的矩阵（UB）</th></tr></thead><tbody><tr><td>float</td><td>int8_t、uint8_t、half、bfloat16_t、float。</td></tr><tr><td>int32_t</td><td>int8_t、uint8_t、half、int32_t。</td></tr></tbody></table></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002549846732_section2045914466492"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>对于量化输入为float32数据类型的说明如下： <ul><li>标准的IEEE 754 float32格式为：1bit符号位，8bits指数位，23bits尾数位；当前AI处理器支持的float32格式为：1bit符号位，8bits指数位，10bits尾数位。</li><li>如果用户提供的是标准的IEEE 754 float32输入，API内部会处理成处理器支持的float32格式进行计算，此时如果golden数据生成过程中使用的是标准的IEEE 754 float32数据，则可能引入精度不匹配问题，需要修正golden数据的生成，将量化参数的23bits尾数位的低13bits数据位清零再参与量化计算。</li></ul></li><li>源矩阵NZ格式地址要求64字节对齐，目的矩阵NZ格式地址需要满足32字节对齐。</li><li>当搬出的mSize、nSize或者ndNum中的任意一个值为0时，该指令不会被执行。ndNum=0时会报warning。</li><li>量化和ReLU参数不能为inf/nan和非规格化数。</li><li>目标数据不能有重叠。如果对目的地址有重叠写入，硬件不会报告任何警告和错误，也不保证重叠数据的写入顺序。</li><li>unitFlag特性开启需要配合Mmad同时开启。</li></ul><div data-filter="950"><ul><li><p>dualDstCtrl仅支持在普通搬运模式（NZ2NZ）或NZ2ND搬运场景下使用，不支持随路功能场景。</p></li><li><p>当启用NZ2DN且srcNzC0Stride不等于1时，不能同时开启unitFlag。</p></li><li><p>该接口仅适用于Mix算子场景，且仅支持Cube核数与Vector核数比例为1:2的配置。在该场景下，subBlockId仅支持取值0或1。</p></li><li><p>Ascend 950PR/Ascend 950DT特殊值/边界值约束说明：</p><p>对于浮点类型inf/nan输入输出，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行设置，控制浮点数量化搬出时的饱和模式；</p><p>对于fp8_e4m3fn_t类型，可以通过CTRL寄存器（控制寄存器）的CTRL[48]比特位进行更精细的设置；</p><ul><li><p>非饱和模式：CTRL[48]设置成1&#39;b1，inf/nan保持原输出。对于fp8_e4m3fn_t类型，若结果的绝对值为inf或大于fp8_e4m3fn_t的最大规格化值，则输出结果为nan。</p></li><li><p>饱和模式：CTRL[48]设置成1&#39;b0，inf输出会被饱和为±MAX， nan输出会被饱和为0。对于fp8_e4m3fn_t类型，当CTRL[50]设置成1&#39;b0时，nan被转换为零，当CTRL[50]设置成1&#39;b1时，nan保持不变，若结果的绝对值为inf或大于fp8_e4m3fn_t的最大规格化值，则结果为最大规格化值。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 设置CTRL[48]为0，开启浮点数饱和模式</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">AscendCUtils</span><span class="o">::</span><span class="n">SetOverflow</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
</code></pre></div></li></ul><p>对于整数类型只有饱和模式。 L0C Buffer到UB搬运接口的边界值汇总请见<a href="../../../../appendix/matrix_compute_move_out_interface_boundary_value_summary.html">矩阵计算搬出相关接口边界值汇总</a>。</p></li></ul></div><div data-filter="950"><h2 id="关键特性说明">关键特性说明<a class="header-anchor" href="#关键特性说明">​</a></h2><p>以下图片和说明仅适用于Ascend 950PR/Ascend 950DT：</p><h3 id="不开启NZ2ND随路格式转换">不开启NZ2ND随路格式转换<a class="header-anchor" href="#不开启NZ2ND随路格式转换">​</a></h3><p>不开启NZ2ND的情况下，参数设置示例（通过Fixpipe接口搬运并去除dummy数据）和解释说明如下：</p><p>当M方向上的数据元素个数不是16的倍数时，搬入时会额外读取dummy数据，并在写入目标位置后丢弃这些dummy数据。矩阵块被定义为连续的16*16的数据块，数据块的个数为M/16向上取整，矩阵块的长度为M*16*sizeof(T)，T是数据类型。</p><p><strong>单搬运模式：</strong></p><ul><li>nSize = 48，表示源NZ矩阵中待搬运矩阵（图中蓝色区域）在N方向上的大小为48个元素。</li><li>mSize = 24，表示源NZ矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>srcStride = 64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个蓝色Z排布的起始地址与第二个蓝色Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 40 * C0，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中第一个蓝色Z排布的起始地址与第二个蓝色Z排布的起始地址之间的间隔为40 * 16个元素。</li></ul><p><strong>图1</strong> 不开启NZ2ND参数的单搬运模式设置示意图<span id="fig128961542184620"></span></p><p><img src="`+i+'" alt title="不开启NZ2ND参数的单搬运模式设置示意图"></p><p><strong>双目标控制模式：</strong></p><p>在普通搬运模式下启用双目标模式如下图所示，分为按M维度拆分和按N维度拆分，按M维度拆分M必须为2的倍数，按N维度拆分N必须为32的倍数：</p><p>N方向切分：</p><ul><li>nSize = 32，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵中待搬运矩阵在M方向上的大小为48个元素。</li><li>srcStride = 64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 64 * C0，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中UB0中Z排布的起始地址与UB1中Z排布的起始地址之间的间隔为64 * 16个元素。</li></ul><p>M方向切分：</p><ul><li>nSize = 32，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li>mSize = 24，表示源NZ矩阵中待搬运矩阵在M方向上的大小为24个元素。</li><li>srcStride = 64，表示源NZ矩阵中待搬运矩阵相邻Z排布的起始地址偏移，即下图中第一个块Z排布矩阵的起始地址与第二个Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 40 * C0，表示目的NZ矩阵中相邻Z排布的起始地址偏移，即下图中UB0（或UB1）中第一个Z排布的起始地址与第二个Z排布的起始地址之间的间隔为40 * 16个元素。</li></ul><p><strong>图2</strong> 不开启NZ2ND参数和NZ2DN参数的双目标搬运模式设置示意图<span id="fig6561154491913"></span></p><p><img src="'+c+'" alt title="不开启NZ2ND参数和NZ2DN参数的双目标搬运模式设置示意图"></p><h3 id="开启NZ2ND随路格式转换">开启NZ2ND随路格式转换<a class="header-anchor" href="#开启NZ2ND随路格式转换">​</a></h3><p>开启NZ2ND的情况下，参数设置示例和解释说明如下：</p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2。图中蓝色区域为NZ矩阵1，紫色区域为NZ矩阵2。</li><li>nSize = 32，表示源NZ矩阵（图中蓝色区域）在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 64，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图中第一个蓝色Z排布的起始地址与第二个蓝色Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 64，表示目的ND矩阵每一行中的元素个数为64。</li><li>srcNdStride = 16，表示不同NZ矩阵起始地址之间的间隔为16 * 16 * C0_Size。</li><li>dstNdStride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul><p><strong>图3</strong> 开启NZ2ND参数设置示意图<span id="fig79783143556"></span></p><p><img src="'+e+'" alt title="开启NZ2ND参数设置示意图"></p><p><strong>单搬运模式：</strong></p><ul><li>ndNum = 2，表示源NZ矩阵的数目为2。图中蓝色区域为NZ矩阵1，紫色区域为NZ矩阵2。</li><li>nSize = 32，表示源NZ矩阵（图中蓝色区域）在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 64，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图中第一个蓝色Z排布的起始地址与第二个蓝色Z排布的起始地址之间的间隔为64 * C0_Size。</li><li>dstStride = 64，表示目的ND矩阵每一行中的元素个数为64。</li><li>srcNdStride = 256，表示不同NZ矩阵起始地址之间的间隔为256，单位为C0_Size。</li><li>dstNdStride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul><p><strong>图4</strong> 开启NZ2ND参数的单搬入模式设置示意图<span id="fig11991024112516"></span></p><p><img src="'+r+'" alt title="开启NZ2ND参数的单搬入模式设置示意图"></p><p><strong>双目标控制模式：</strong></p><ul><li><p>ndNum = 2，表示源NZ矩阵的数目为2。图中红框区域为矩阵1，蓝框区域为矩阵2。</p></li><li><p>nSize = 32，表示源NZ矩阵（图中红框区域或蓝框区域）在N方向上的大小为32个元素。</p></li><li><p>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</p></li><li><p>srcStride = 64，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图红框区域中左侧浅色Z排布矩阵的起始地址与右侧深色Z排布矩阵的起始地址之间的间隔为64 * C0_Size。</p></li><li><p>dstStride = 64，表示目的ND矩阵每一行中的元素个数为64。</p></li><li><p>ndNum = 2，表示源NZ矩阵的数目。</p></li><li><p>srcNdStride = 240，表示不同NZ矩阵起始地址之间的间隔为240 * C0_Size。</p></li><li><p>dstNdStride = 4096，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</p><p><strong>图5</strong> 开启NZ2ND参数双搬入模式设置示意图<span id="fig8810182815117"></span></p><p><img src="'+d+'" alt title="开启NZ2ND参数双搬入模式设置示意图"></p></li></ul><h3 id="开启NZ2DN随路格式转换">开启NZ2DN随路格式转换<a class="header-anchor" href="#开启NZ2DN随路格式转换">​</a></h3><p>开启NZ2DN的情况下，参数设置示例和解释说明如下：</p><p><strong>单搬运模式：</strong></p><p>示例一，参数取值说明如下，示意图见<a href="#fig19772110476">图6</a>：</p><ul><li>dnNum = 2，表示源NZ矩阵的数目为2。图中蓝色区域为NZ矩阵1，紫色区域为NZ矩阵2。</li><li>nSize = 32，表示源NZ矩阵（图中蓝色区域）在N方向上的大小为32个元素。</li><li>mSize = 48，表示源NZ矩阵在M方向上的大小为48个元素。</li><li>srcStride = 80，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图中相邻两块蓝色Z排布的起始地址之间的间隔为80 * C0_Size。</li><li>dstStride = 80，表示目的DN矩阵每一行中的元素个数为80。</li><li>ndNum = 2，表示源NZ矩阵的数目。</li><li>srcNzMatrixStride = 240，表示不同源NZ矩阵的偏移，即下图中第一个蓝色Z排布的起始地址和第二个紫色Z排布的起始地址之间的间隔为240 * C0_Size。</li><li>srcNzC0Stride = 1：表示源矩阵NZ分形相邻行的地址偏移。</li><li>dstDnMatrixStride：表示相邻DN矩阵起始地址间的偏移为48 * 80 =3840个元素。</li></ul><p><strong>图6</strong> 开启NZ2DN单搬运模式示意图1<span id="fig19772110476"></span></p><p><img src="'+o+'" alt title="开启NZ2DN单搬运模式示意图1"></p><p>示例二，参数取值说明如下，示意图见<a href="#fig769114585716">图7</a>：</p><ul><li>dnNum = 2，表示源NZ矩阵的数目为2。图中蓝色区域为NZ矩阵1，红色区域为NZ矩阵2。</li><li>nSize = 24，表示源NZ矩阵（图中蓝色区域）在N方向上的大小为24个元素。</li><li>mSize = 24，表示源NZ矩阵在M方向上的大小为24个元素。</li><li>srcStride = 80，表示源NZ矩阵中相邻Z排布的起始地址偏移，即下图中相邻两块蓝色Z排布的起始地址之间的间隔为80 * C0_Size。</li><li>dstStride = 60，表示目的DN矩阵每一行中的元素个数为60。</li><li>ndNum = 2，表示源NZ矩阵的数目。</li><li>srcNzMatrixStride = 240，表示不同源NZ矩阵的偏移，即下图中第一个蓝色Z排布的起始地址和第二个紫色Z排布的起始地址之间的间隔为240 * C0_Size。</li><li>srcNzC0Stride = 2：表示源矩阵NZ分形相邻行的地址偏移。</li><li>dstDnMatrixStride：表示相邻DN矩阵起始地址间的偏移为48 * 60 = 2880个元素。</li></ul><p><strong>图7</strong> 开启NZ2DN单搬运模式示意图2<span id="fig769114585716"></span></p><p><img src="'+_+`" alt title="开启NZ2DN单搬运模式示意图2"></p></div><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002549846732_section088124295117"></span><a class="header-anchor" href="#调用示例">​</a></h2><div data-filter="950"><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2ub">fixpipe_l0c2ub样例</a>。</p><ul><li><p>示例：通路L0C Buffer-&gt;UB。输入A矩阵和B矩阵的数据类型为half，输出C矩阵为float，默认配置开启Nz2Nd的格式转换。完整样例可以参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2ub">样例链接</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// L0C Buffer-&gt;UB 搬运，目的位置为UB，需将FixpipeConfig的isToUB配置为true。</span>
<span class="k">constexpr</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">FixpipeConfig</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR_UB</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="n">AscendC</span><span class="o">::</span><span class="n">CO2Layout</span><span class="o">::</span><span class="n">ROW_MAJOR</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">};</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">outputType</span><span class="o">&gt;</span><span class="w"> </span><span class="n">cUB</span><span class="p">;</span>
<span class="n">cUB</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">outputType</span><span class="o">&gt;</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">VECOUT</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">cSingleSize</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">FixpipeParamsArch3510</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">CO2Layout</span><span class="o">::</span><span class="n">ROW_MAJOR</span><span class="o">&gt;</span><span class="w"> </span><span class="n">fixpipeParams</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">mSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseM</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">nSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseN</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">baseM</span><span class="p">,</span><span class="w"> </span><span class="n">CUBE_BLOCK</span><span class="p">);</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">baseN</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Fixpipe</span><span class="o">&lt;</span><span class="n">outputType</span><span class="p">,</span><span class="w"> </span><span class="n">l0cType</span><span class="p">,</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR_UB</span><span class="o">&gt;</span><span class="p">(</span><span class="n">cUB</span><span class="p">,</span><span class="w"> </span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">fixpipeParams</span><span class="p">);</span>
</code></pre></div></li></ul></div></article></div>`,1)])])}const F=n(u,[["render",N]]);export{S as __pageData,F as default};
